// Generated by `uv run python -m app.tools.typescript` (backend/) from the tools' declared result models.
// Don't edit by hand: change the model in backend/app/tools/, then run the command again.

/** One CVE's verdict. */
export interface AffectedOne {
  n: number
  id: string
  product: string
  severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE' | null
  verdict: 'affected' | 'not_affected' | 'unknown'
  reason: string
  fixed_version: string | null
  who_acts: 'you' | 'upstream' | 'vendor'
  usage: string
  version: string | null
  watch_status: 'open' | 'fixed' | 'not_affected' | 'accepted' | 'not_watched'
  possible_match: boolean
  note: string
}

/** A watched product's open CVEs by verdict. */
export interface AffectedProduct {
  product: string
  usage: string
  version: string | null
  open: number
  counts: VerdictCounts
  cves: AffectedRow[]
  who_acts: 'you' | 'upstream' | 'vendor' | null
  note: string
}

export interface VerdictCounts {
  affected: number
  unknown: number
  not_affected: number
}

export interface AffectedRow {
  id: string
  severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE' | null
  verdict: 'affected' | 'not_affected' | 'unknown'
  reason: string
  fixed_version: string | null
}

/** lookup_cve: one CVE with its OWASP, KEV, EPSS and watchlist context, the verdict and the priority. */
export interface CveResult {
  n: number
  id: string
  product: string
  published: string
  severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE' | null
  cvss: number | null
  cwes: string[]
  owasp: Category | null
  description: string
  url: string
  kev: Kev | null
  watch_status: 'open' | 'fixed' | 'not_affected' | 'accepted' | 'not_watched'
  epss: Epss | null
  product_match: 'confirmed' | 'conflicting' | 'unknown' | null
  possible_match: boolean
  verdict: 'affected' | 'not_affected' | 'unknown'
  verdict_reason: string
  fixed_version: string | null
  who_acts: 'you' | 'upstream' | 'vendor'
  no_fix: boolean
  decision: Decision | null
  review_due: boolean
  open_days: number
  priority: Priority | null
}

/** An OWASP Top 10 category. */
export interface Category {
  code: string
  title: string
  url: string
}

export interface Kev {
  date_added: string
  deadline: string
  ransomware: string
  required_action: string
}

export interface Epss {
  score: number
  percentile: number
  date: string
}

/** The user's current decision record (app.status, A16b). */
export interface Decision {
  status: 'open' | 'fixed' | 'not_affected' | 'accepted'
  justification: 'component_not_present' | 'vulnerable_code_not_present' | 'vulnerable_code_not_in_execute_path' | 'vulnerable_code_cannot_be_controlled_by_adversary' | 'inline_mitigations_already_exist' | null
  reason: string | null
  note: string | null
  review_date: string | null
  compensating_control: string | null
  decided_at: string | null
  decided_by: string | null
  via: string | null
}

export interface Priority {
  level: 'urgent' | 'high' | 'normal' | 'low'
  reasons: string[]
  due_date: string
  due_from: string
  overdue: boolean
  alert_priority: number
}

/** prioritise: the top open CVEs in the rules' order, and the view they come from. */
export interface FixFirstResult {
  filters: Filters
  ignored: string[]
  product: string | null
  total_open: number
  cves: FixFirstCve[]
  note: string
}

/** The view's filters that were applied (CveView's names, without status). A filter that isn't set is absent. */
export interface Filters {
  product?: string
  severity?: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW'
  verdict?: 'affected' | 'not_affected' | 'unknown'
  kev?: boolean
  since?: string
}

export interface FixFirstCve {
  rank: number
  n: number
  id: string
  product: string
  severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE' | null
  kev: boolean
  epss_percentile: number | null
  verdict: 'affected' | 'not_affected' | 'unknown'
  status: 'open' | 'accepted'
  review_due: boolean
  priority: 'urgent' | 'high' | 'normal' | 'low'
  reasons: string[]
  due_date: string
  due_from: string
  overdue: boolean
  no_fix: boolean
  open_days: number
}

/** search_security: the translated query and the numbered sources. */
export interface SearchResult {
  query: QueryInfo
  sources: FoundSource[]
}

export interface QueryInfo {
  original: string
  semantic_query: string
  rewrites: string[]
  filters: Record<string, string>
  dropped_filters: string[]
  relaxed: boolean
  found_by?: Record<string, string[]>
}

/** A numbered source with its full chunk text. A field the chunk doesn't have is absent. */
export interface FoundSource {
  n: number
  doc_id: string
  doc_type: 'owasp_llm' | 'owasp_web' | 'atlas_technique' | 'atlas_mitigation' | 'atlas_case' | 'cve'
  title: string
  section?: string
  date?: string
  product?: string
  severity?: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE'
  kev?: boolean
  text: string
}

/** update_watchlist: what changed, and the watchlist after it. */
export interface WatchlistResult {
  message: string
  watchlist: string[]
}

/** explain_weakness for a CWE: its OWASP Top 10 category and the snapshot's CVEs with it. */
export interface CweResult {
  kind: 'cwe'
  id: string
  url: string
  category: Category | null
  cves_in_snapshot: number
  examples: CweExample[]
}

/** explain_weakness for an ATLAS technique: tactics, mitigations and the LLM Top 10 risks citing it. */
export interface TechniqueResult {
  kind: 'atlas_technique'
  id: string
  name: string
  url: string
  tactics: string[]
  maturity: string
  description: string
  parent: string | null
  subtechniques: Named[]
  mitigations: Named[]
  cited_by_llm_top10: CitedBy[]
  case_studies: number
}

export interface CweExample {
  id: string
  product: string
  severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE' | null
}

export interface Named {
  id: string
  name: string
}

export interface CitedBy {
  code: string
  title: string
}

/** Each tool's result, by the tool's name. */
export interface ToolResults {
  check_affected: AffectedOne | AffectedProduct
  lookup_cve: CveResult
  prioritise: FixFirstResult
  search_security: SearchResult
  update_watchlist: WatchlistResult
  explain_weakness: CweResult | TechniqueResult
}

export type ToolName = keyof ToolResults

/** A tool call's name and result together: check the name, and the result has that tool's type. An unknown tool's
 *  call never has a result. */
export type NamedResult =
  | { [K in ToolName]: { name: K; result: ToolResults[K] | null } }[ToolName]
  | { name: string; result: null }
